import * as THREE from './three.module.js';
import {COURT as C} from './court-geometry.js';
import {beam} from './venue-tools.js';
export function buildTimberRafters(){const root=new THREE.Group(),trusses=[],timber=new THREE.MeshStandardMaterial({color:'#6a4b30',roughness:.9,transparent:true,opacity:.22,depthWrite:false}),rear=C.halfLength+(C.halfLength-C.endRoofInner);root.userData.timberRafters=true;for(let z=-C.halfLength+1;z<rear;z+=4.5){const g=new THREE.Group();g.userData.trussZ=z;root.add(g);trusses.push(g);const left=[C.roofOuterX,7.85,z],ridge=[-1.08,10.1,z],right=[5,7.85,z];for(const [a,b,r]of [[left,ridge,.12],[ridge,right,.12],[left,right,.075]])beam(g,a,b,r,timber);for(const x of [-5.7,-3.4,-1.08,1.2,3.6]){const y=10.1-Math.abs(x+1.08)/6.1*2.25;beam(g,[x,7.85,z],[x,y,z],.045,timber);beam(g,[x,7.85,z],[Math.min(4.8,x+1.5),Math.min(10.1,y+.2),z],.035,timber);}}let active=false,overview=false;return {root,setVisible(on,over=false){active=on;overview=over;root.visible=on&&!over;},setEndView(side){for(const g of trusses)g.visible=active&&!overview&&g.userData.trussZ*side<7;}};}
